
from pathlib import Path
from dataclasses import dataclass

@dataclass
class SerialDevice:
    path: str
    source: str

def discover_serial():
    devices=[]
    byid=Path("/dev/serial/by-id")
    if byid.exists():
        for p in sorted(byid.iterdir()):
            devices.append(SerialDevice(str(p),"by-id"))
    for pattern in ("/dev/ttyUSB*","/dev/ttyACM*"):
        for p in Path("/dev").glob(pattern.split("/dev/")[1]):
            devices.append(SerialDevice(str(p),"legacy"))
    return devices

def validate_cni(host:str, port:int)->bool:
    return bool(host) and 1 <= port <= 65535
